"""Serial event-transport adaptation of the cached partial gather barrier.

The barrier owns the local coordinator round ``r``, the cached raw per-worker
edge loads ``A[w, e]``, the seen/fresh endpoint sets and the per-worker last
acceptance round.  A step may only advance when every endpoint has been seen,
at least ``min_arrival`` distinct endpoints are fresh and no seen endpoint is
older than ``max_lag`` (equality allowed).
"""
import numpy as np


class PartialBarrier:

    def __init__(self, number_of_endpoints, min_arrival, max_lag, num_edges):
        self._number_of_endpoints = number_of_endpoints
        self._min_arrival = min_arrival if min_arrival is not None else number_of_endpoints
        self._max_lag = max_lag
        self._clock = 0
        self._arrival_set = set()
        self._storage = np.zeros((number_of_endpoints, num_edges))
        self._initial_response_set = set(range(number_of_endpoints))
        self._last_response = [None] * number_of_endpoints

    @property
    def clock(self):
        return self._clock

    @property
    def storage(self):
        return self._storage

    @property
    def arrivals(self):
        return set(self._arrival_set)

    @property
    def seen(self):
        return set(range(self._number_of_endpoints)) - self._initial_response_set

    @property
    def last_response(self):
        return list(self._last_response)

    def reset(self):
        """Generation reset: zero cache, empty seen/fresh, absent ages."""
        self._clock = 0
        self._arrival_set = set()
        self._storage = np.zeros(self._storage.shape)
        self._initial_response_set = set(range(self._number_of_endpoints))
        self._last_response = [None] * self._number_of_endpoints

    def ages(self):
        seen = self.seen
        return [None if w not in seen else self._clock - self._last_response[w]
                for w in range(self._number_of_endpoints)]

    def blockers(self):
        """Return ``(missing, stale)``: unseen endpoints and stale endpoints."""
        missing = sorted(self._initial_response_set)
        stale = []
        for w in self.seen:
            if self._clock - self._last_response[w] > self._max_lag:
                stale.append(w)
        return missing, sorted(stale)

    def can_advance(self):
        if self._initial_response_set:
            return False
        if len(self._arrival_set) < self._min_arrival:
            return False
        for w in self.seen:
            if self._clock - self._last_response[w] > self._max_lag:
                return False
        return True

    def arrive(self, node_id, response):
        """Cache one accepted proposal; marks the endpoint seen and fresh."""
        self._storage[node_id, :] = np.asarray(response, dtype=float)
        self._initial_response_set.discard(node_id)
        self._arrival_set.add(node_id)
        self._last_response[node_id] = self._clock

    def advance(self):
        """Advance one round; returns ``False`` without changing anything."""
        if not self.can_advance():
            return False
        self._clock += 1
        self._arrival_set = set()
        return True

    def snapshot(self):
        return {'clock': self._clock,
                'arrivals': set(self._arrival_set),
                'storage': np.array(self._storage, dtype=float, copy=True),
                'unseen': set(self._initial_response_set),
                'last': list(self._last_response)}

    def restore(self, state):
        self._clock = state['clock']
        self._arrival_set = set(state['arrivals'])
        self._storage = np.array(state['storage'], dtype=float, copy=True)
        self._initial_response_set = set(state['unseen'])
        self._last_response = list(state['last'])
