"""One-domain CPU controller backend; normalized capacities, no external LP runtime.

The controller projection of PROTOCOL.md picks a signed consensus vector ``z``
and a ceiling ``h`` minimising ``h + 0.5*rho*sum_live (z-V)**2`` under
``z[e] <= h`` with ``h >= 0`` in ``route`` mode, and ``0.5*rho*sum_live
(z-V)**2`` under ``z[e] <= 1`` with ``h = 1`` in ``admit`` mode.  Because the
per-edge penalty is separable the optimal ``z`` is ``min(V, h)`` and the route
ceiling is the exact root of the piecewise linear ``S(h) = sum (V-h)_+ = 1/rho``.
"""
import math
import numpy as np


class PDLPMLU:

    def __init__(self, num_edges, rho, mode):
        self._num_edges = num_edges
        self._num_domains = 1
        self._objective = mode
        self._NUM_VARIABLES = num_edges + 1
        self._NUM_CONSTRAINTS = num_edges
        self.rho = rho
        self.alpha = 1.0
        self._solved = False
        self._current_F = np.zeros(num_edges)
        self.active = np.ones(num_edges, dtype=bool)
        self._solution = np.zeros(num_edges + 1)
        self.pressure = np.zeros(num_edges)

    @property
    def num_edges(self):
        return self._num_edges

    @property
    def num_domains(self):
        return self._num_domains

    @property
    def is_mlu(self):
        return self._objective == 'route'

    def update_F_m(self, new_F, rho=None):
        if rho is not None:
            self.rho = rho
        self._current_F = np.array(new_F, dtype=np.float64).flatten()
        self._solved = False

    def solve(self):
        """Return ``(z, h, t)`` for the cached target vector and penalty."""
        V = np.asarray(self._current_F, dtype=float)
        live = self.active
        rho = float(self.rho)
        n = V.size
        z = np.zeros(n)
        t = np.zeros(n)
        if not bool(live.any()):
            h = 1.0 if not self.is_mlu else 0.0
            self._solution = np.concatenate([z, [h]])
            self.pressure = t
            self._solved = True
            return z, h, t
        Vl = V[live]
        if self.is_mlu:
            pos = Vl[Vl > 0.0]
            if pos.size == 0 or rho * math.fsum(pos.tolist()) <= 1.0:
                h = 0.0
            else:
                h = self._ceiling(np.sort(Vl)[::-1], rho)
            zl = np.minimum(Vl, h)
        else:
            h = 1.0
            zl = np.minimum(Vl, 1.0)
        tl = rho * (Vl - zl)
        if self.is_mlu and h > 0.0:
            tl = self._balance(Vl, zl, tl, rho)
        z[live] = zl
        t[live] = tl
        self._solution = np.concatenate([z, [h]])
        self.pressure = t
        self._solved = True
        return z, h, t

    @staticmethod
    def _ceiling(sorted_desc, rho):
        """Exact root of ``sum_i (V_i - h)_+ = 1/rho`` on the live edges."""
        m = int(sorted_desc.size)
        prefix = np.cumsum(sorted_desc)
        inv = 1.0 / rho
        for k in range(1, m + 1):
            hk = (float(prefix[k - 1]) - inv) / k
            low = float(sorted_desc[k]) if k < m else 0.0
            if hk >= low and hk < float(sorted_desc[k - 1]):
                return hk
        # safeguard: monotone bisection on S(h) = sum (V-h)_+
        lo, hi = 0.0, float(sorted_desc[0])
        for _ in range(200):
            mid = 0.5 * (lo + hi)
            if rho * math.fsum(np.maximum(sorted_desc - mid, 0.0).tolist()) > 1.0:
                lo = mid
            else:
                hi = mid
        return 0.5 * (lo + hi)

    @staticmethod
    def _balance(V, z, t, rho):
        """Nudge the positive pressure so the reported ``sum t`` is exactly one."""
        idx = np.flatnonzero(V > z)
        if idx.size == 0:
            return t
        raw = t[idx]
        total = math.fsum(raw.tolist())
        if total <= 0.0:
            return t
        raw = raw * (1.0 / total)
        resid = 1.0 - math.fsum(raw.tolist())
        if resid:
            raw[int(np.argmax(raw))] += resid
        out = np.array(t, dtype=float, copy=True)
        out[idx] = raw
        return out

    @property
    def current_u(self):
        return float(self._solution[-1])

    @property
    def current_Z(self):
        return self._solution[:-1]
